SELECT quantity_bucket, unit_price_bucket, quantity_range, cnt FROM (SELECT CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END AS unit_price_bucket, MAX(quantity) - MIN(quantity) AS quantity_range, COUNT(*) AS cnt FROM order_items WHERE unit_price > 310 GROUP BY CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END, CASE WHEN unit_price >= 350 THEN 'high' WHEN unit_price >= 160 THEN 'mid' ELSE 'low' END) AS agg WHERE quantity_range < 70 ORDER BY unit_price_bucket DESC, 1;
